var EXTRA=[{dot:"gray",j:"Orthopadie",h:"LCA con peroneo lungo: caviglia invariata a sei mesi",v:"Studio non randomizzato in soli uomini: il punteggio del ginocchio migliora e quelli della caviglia restano invariati, con un piccolo aumento dell'indice dell'arco plantare; follow-up breve, campione piccolo, nessun confronto con altri innesti.",pmid:'42811158',doi:'10.1007/s00132-026-04892-z',temi:["LCA", "peroneo lungo", "innesto"]},{dot:"gray",j:"BMC Musculoskeletal Disorders",h:"Rilascio retinacolare laterale con cartilagine: miglioramenti mantenuti a undici anni",v:"Serie retrospettiva su artrosi femororotulea isolata, con esclusione dell'instabilità: i punteggi restano sopra il basale dopo il picco dei due anni, nessuna revisione; campione piccolo e nessun gruppo di controllo.",pmid:'42786458',doi:'10.1186/s12891-026-10358-2',temi:["femororotuleo", "cartilagine", "lungo termine"]},{dot:"gray",j:"Osteoarthritis and Cartilage",h:"Lettera su INKA: comparatore monocompartimentale e non inferiorità",v:"Lettera senza abstract: dal titolo discute se un comparatore arricchito di protesi monocompartimentali incida sulla conclusione di non inferiorità del trial; il contenuto non è stato letto, va verificato aprendo la lettera.",pmid:'42805398',doi:'10.1016/j.joca.2026.09.010',temi:["protesi monocompartimentale", "non inferiorità", "trial"]},{dot:"gray",j:"Arthroscopy",h:"Displasia trocleare: l'indice patello-trocleare misura contatto, non contenimento",v:"Commento editoriale: un indice normale non basta a escludere un ginocchio displasico dalla distalizzazione della tuberosità, e né questo né il Caton-Deschamps correlano con l'angolo di risoluzione dell'instabilità in anestesia. È un'opinione, non uno studio.",pmid:'42798291',doi:'10.1002/arj.70647',temi:["displasia trocleare", "altezza rotulea", "instabilità rotulea"]},{dot:"gray",j:"Arthroscopy",h:"Altezza rotulea: meglio misure semplici",v:"Commento editoriale sull'affidabilità e sulla rilevanza clinica degli indici di altezza rotulea nella stabilizzazione femororotulea personalizzata; opinione, senza dati propri nell'abstract.",pmid:'42803659',doi:'10.1002/arj.70571',temi:["altezza rotulea", "instabilità rotulea", "indici radiografici"]},{dot:"gray",j:"The Knee",h:"Osteotomia della tuberosità ripetuta nella re-revisione protesica: consolidazione elevata",v:"Serie di un centro con osteotomie sequenziali: la gran parte consolida e le complicanze dei tessuti molli mancano; retrospettiva, senza confronto, in un contesto di revisione complessa.",pmid:'42790394',doi:'10.1016/j.knee.2026.104643',temi:["revisione protesica", "osteotomia tuberosità", "consolidazione"]},{dot:"gray",j:"Indian Journal of Orthopaedics",h:"Dopo LCA con hamstring l'asse coronale resta invariato a cinque anni",v:"Coorte retrospettiva: nessuna differenza di allineamento fra ginocchio operato e controlaterale; la deviazione in varo si associa a punteggi più bassi con correlazione debole; solo hamstring, nessun confronto con altri innesti.",pmid:'42824328',doi:'10.1007/s43465-026-01699-0',temi:["LCA", "allineamento coronale", "hamstring"]},{dot:"gray",j:"Sports (Basel)",h:"Calciatrici: asimmetria del core e side-hop associate a lesioni del ginocchio",v:"Coorte prospettica di giocatrici d'élite con un anno di osservazione: le asimmetrie di forza e di salto laterale precedono le lesioni, ma gli eventi sono pochi, il modello è esplorativo e l'associazione non prova che correggerle prevenga lesioni.",pmid:'42784406',doi:'10.3390/sports14090410',temi:["prevenzione", "calcio femminile", "asimmetrie"]},{dot:"gray",j:"Frontiers in Surgery",h:"Artroscopio ad angolo regolabile per il tunnel femorale del LCA: prova sul maiale",v:"Studio esplorativo su dieci ginocchia di maiale, descrittivo: la posizione del tunnel è confrontata con l'artroscopio a trenta gradi; il chirurgo era membro del gruppo che sviluppa il dispositivo, nessun dato sull'uomo.",pmid:'42787401',doi:'10.3389/fsurg.2026.1899167',temi:["LCA", "tunnel femorale", "strumentazione"]},{dot:"gray",j:"Orthopedics",h:"Ottantenni e protesi totale: più rischio medico, meno revisioni a un anno",v:"Analisi di un database statunitense di richieste assicurative su centinaia di migliaia di interventi: le differenze sono date come significative senza dimensioni dell'effetto nell'abstract; il database non mostra esiti funzionali.",pmid:'42775938',doi:'10.3928/01477447-20260820-01',temi:["protesi totale", "età avanzata", "revisione"]},{dot:"gray",j:"Diagnostics",h:"Lateralizzazione rotulea in risonanza associata alla gravità dell'artrosi femororotulea",v:"Studio retrospettivo su risonanze: la distanza di lateralizzazione è maggiore nell'artrosi grave, con accordo fra lettori eccellente; disegno trasversale, nessuna causalità.",pmid:'42793781',doi:'10.3390/diagnostics16182997',temi:["femororotuleo", "risonanza magnetica", "lateralizzazione"]}];
var SCOPERTE=[{t:"Dopo il LCA il deficit del quadricipite può avere una componente nel cervello?",v:"Un laboratorio di riabilitazione (PRIME) combina risonanza funzionale, tensori di diffusione e stimolazione magnetica transcranica su 10 persone con LCA ricostruito e 9 controlli, per capire se il volume del tratto corticospinale condiziona il legame fra attivazione corticale, eccitabilità e forza del quadricipite. Vale la deviazione perché sposta la riabilitazione dal muscolo al sistema nervoso; con 19 partecipanti è un'ipotesi, non una prova.",pmid:'42774227',doi:'10.3389/fnhum.2026.1888579',temi:["LCA", "neuroscienze", "forza del quadricipite"]},{t:"Un impianto stampato in 3D per la cartilagine, in nylon permanente, messo alla prova sulla capra",v:"Studio pilota su sei capre: microfrattura più impianto con riempimento del 45% dà un punteggio istologico mediano di 44 contro 33 della sola microfrattura a 16 settimane (p<0,05), ma il materiale non si riassorbe e provoca una reazione cronica da corpo estraneo. Vale la deviazione perché è bioingegneria vicina alla tua cartilagine (AMIC, minced); il campione istologico è di tre difetti per braccio e il patologo non era in cieco.",pmid:'42817817',doi:'10.1177/19476035261487354',temi:["cartilagine", "bioingegneria", "microfrattura"]},{t:"Agopuntura con ago caldo più tuina nell'artrosi: la meta-analisi misura citochine, non dolore",v:"Una meta-analisi di 19 RCT (8 database, fino a marzo 2026) di un reparto di medicina tradizionale cinese riporta che il trattamento combinato abbassa CRP, IL-6, TNF-alfa e MMP-3 (per esempio CRP: differenza media standardizzata −2,58, IC 95% da −4,49 a −0,67). Vale la deviazione perché è un altro modo di pensare l'artrosi; sono marcatori di laboratorio e non esiti clinici, gli effetti sono insolitamente grandi e il rischio di bias non è stato letto oltre l'abstract.",pmid:'42802793',doi:'10.2147/JPR.S636990',temi:["agopuntura", "artrosi", "medicina tradizionale cinese"]}];
var SOC={"1": {"video": "Quando la rotula tende a uscire dalla sua sede si può ricostruire il legamento che la trattiene, il legamento femororotuleo mediale. Sul femore si fissa di solito dentro un tunnel scavato nell'osso. Una revisione di studi, uscita a settembre 2026, ha messo insieme ottanta lavori su quattromilacento adulti operati solo di questo legamento e ha guardato se la fissazione sulla superficie dell'osso, senza tunnel, dia risultati simili.\n\nIl punteggio funzionale del ginocchio, il Kujala, è in media 87,9 con il tunnel e 91,4 senza tunnel, con intervalli di incertezza che in parte si sovrappongono. La rotula è uscita di nuovo dalla sede nel 2,0% dei casi con il tunnel e nell'1,7% senza. Ma la fissazione senza tunnel riguarda solo duecentoquarantanove persone, circa il sei per cento del totale: la sua stima è meno precisa.\n\nIl limite principale: i due metodi non sono stati confrontati direttamente, sono stati messi accanto gruppi di studi diversi, e l'abstract non descrive che tipo di studi siano. Gli autori concludono che la fissazione senza tunnel sembra paragonabile e può essere un'alternativa sicura quando il tunnel non è possibile. Paragonabile, quindi: non dimostrata migliore.", "linkedin": "Legamento femororotuleo mediale (MPFL): fissarlo al femore con o senza tunnel? Una revisione di 80 studi su 4100 adulti operati solo di questo legamento (The Knee, settembre 2026) confronta il tunnel osseo con la fissazione sulla superficie dell'osso, detta onlay.\n\nPunteggio Kujala medio 87,9 con tunnel e 91,4 con onlay; nuova uscita della rotula 2,0% e 1,7%. Gli intervalli di incertezza si sovrappongono. L'onlay riguarda 249 pazienti, il 6,1% del totale.\n\nLimite: sono gruppi di studi diversi messi accanto, non un confronto diretto, e l'abstract non descrive che studi siano. Gli autori: tecnica comparabile e alternativa sicura quando il tunnel non è possibile, non dimostrata migliore.", "instagram": "Rotula instabile: il legamento che la trattiene si può fissare al femore anche senza tunnel?\nUna revisione di 80 studi su 4100 adulti: risultati simili.\n\nPunteggio del ginocchio 91,4 senza tunnel, 87,9 con tunnel; nuova uscita della rotula 1,7% contro 2,0%. Gli intervalli si sovrappongono.\n\nLimite: la fissazione senza tunnel riguarda solo 249 persone e i gruppi non sono confrontati direttamente.\nFonte: PubMed, PMID 42790393.", "pazienti": "Se la rotula del ginocchio esce più volte dalla sua sede, il chirurgo può ricostruire il legamento che la tiene in posizione. Questo legamento va fissato all'osso della coscia, di solito con un piccolo tunnel. Una revisione di ottanta studi, pubblicata a settembre 2026, riguarda quattromilacento adulti e chiede se si possa fissare il legamento sulla superficie dell'osso, senza tunnel.\n\nNei due gruppi di studi il punteggio di funzione del ginocchio dopo l'operazione è risultato in media simile: 87,9 con il tunnel e 91,4 senza. La rotula è uscita di nuovo dalla sede nel due per cento circa dei casi con il tunnel e nell'1,7% senza. I margini di incertezza si sovrappongono: non si può dire che una differenza ci sia.\n\nIl metodo senza tunnel è stato usato su pochi pazienti, circa duecentocinquanta, e gli studi non confrontano direttamente i due metodi. Per questo i risultati non permettono di dire che uno sia migliore. Gli autori ritengono che possa essere un'alternativa sicura quando il tunnel non è possibile. La scelta della tecnica spetta al chirurgo, in base al singolo caso."}};
var SOCV={"1": {"video": {"chir": ["Instabilità rotulea: nella ricostruzione del legamento femororotuleo mediale, il MPFL, la fissazione femorale si fa quasi sempre con un tunnel osseo. Una revisione sistematica pubblicata su The Knee a settembre 2026 ha raccolto ottanta studi, per quattromilacento pazienti adulti operati di sola ricostruzione del MPFL, senza procedure concomitanti, e ha confrontato il tunnel con la fissazione onlay sul femore. Il quesito è se si possa evitare il tunnel senza perdere in stabilità.", "I numeri. Il Kujala medio postoperatorio è 87,9 con il tunnel, intervallo di confidenza 95% da 86,7 a 89,0, e 91,4 con l'onlay, da 88,6 a 94,1. La ridislocazione è 2,0% con il tunnel, da 1,3 a 2,9, e 1,7% con l'onlay, da 0,47 a 3,78. Gli intervalli si sovrappongono: l'abstract non riporta un confronto diretto fra i due gruppi. L'onlay riguarda duecentoquarantanove pazienti, il 6,1% del totale.", "Il limite: il confronto è indiretto, fra gruppi di studi diversi, e l'abstract non riporta né il disegno degli ottanta studi né il rischio di bias. Con duecentoquarantanove pazienti l'onlay è stimato con molta meno precisione. La conclusione degli autori: comparabile al tunnel, alternativa sicura quando i tunnel non sono possibili. Comparabile, non superiore: è questo che i dati permettono di dire."], "misto": ["Quando la rotula tende a uscire dalla sua sede si può ricostruire il legamento che la trattiene, il legamento femororotuleo mediale. Sul femore si fissa di solito dentro un tunnel scavato nell'osso. Una revisione di studi, uscita a settembre 2026, ha messo insieme ottanta lavori su quattromilacento adulti operati solo di questo legamento e ha guardato se la fissazione sulla superficie dell'osso, senza tunnel, dia risultati simili.", "Il punteggio funzionale del ginocchio, il Kujala, è in media 87,9 con il tunnel e 91,4 senza tunnel, con intervalli di incertezza che in parte si sovrappongono. La rotula è uscita di nuovo dalla sede nel 2,0% dei casi con il tunnel e nell'1,7% senza. Ma la fissazione senza tunnel riguarda solo duecentoquarantanove persone, circa il sei per cento del totale: la sua stima è meno precisa.", "Il limite principale: i due metodi non sono stati confrontati direttamente, sono stati messi accanto gruppi di studi diversi, e l'abstract non descrive che tipo di studi siano. Gli autori concludono che la fissazione senza tunnel sembra paragonabile e può essere un'alternativa sicura quando il tunnel non è possibile. Paragonabile, quindi: non dimostrata migliore."], "pazienti": ["Se la rotula del ginocchio esce più volte dalla sua sede, il chirurgo può ricostruire il legamento che la tiene in posizione. Questo legamento va fissato all'osso della coscia, di solito con un piccolo tunnel. Una revisione di ottanta studi, pubblicata a settembre 2026, riguarda quattromilacento adulti e chiede se si possa fissare il legamento sulla superficie dell'osso, senza tunnel.", "Nei due gruppi di studi il punteggio di funzione del ginocchio dopo l'operazione è risultato in media simile: 87,9 con il tunnel e 91,4 senza. La rotula è uscita di nuovo dalla sede nel due per cento circa dei casi con il tunnel e nell'1,7% senza. I margini di incertezza si sovrappongono: non si può dire che una differenza ci sia.", "Il metodo senza tunnel è stato usato su pochi pazienti, circa duecentocinquanta, e gli studi non confrontano direttamente i due metodi. Per questo i risultati non permettono di dire che uno sia migliore. Gli autori ritengono che possa essere un'alternativa sicura quando il tunnel non è possibile. La scelta della tecnica spetta al chirurgo, in base al singolo caso."]}, "linkedin": {"chir": ["MPFL: fissazione femorale onlay contro tunnel osseo. Revisione sistematica (The Knee, settembre 2026): 80 studi, 4100 pazienti adulti, MPFL isolato, nessuna procedura concomitante. Tunnel 3851 pazienti (93,9%), onlay 249 (6,1%).", "Kujala medio: 87,9 (IC 95% 86,7-89,0) con tunnel, 91,4 (88,6-94,1) con onlay. Ridislocazione: 2,0% (1,3-2,9) contro 1,7% (0,47-3,78). Intervalli sovrapposti; nessun confronto diretto riportato.", "Limiti: confronto indiretto fra gruppi di studi diversi; disegno degli 80 studi e rischio di bias non riportati nell'abstract; onlay stimato su 249 pazienti. Conclusione degli autori: comparabile, alternativa sicura quando il tunnel non è possibile. Comparabile non significa superiore."], "misto": ["Legamento femororotuleo mediale (MPFL): fissarlo al femore con o senza tunnel? Una revisione di 80 studi su 4100 adulti operati solo di questo legamento (The Knee, settembre 2026) confronta il tunnel osseo con la fissazione sulla superficie dell'osso, detta onlay.", "Punteggio Kujala medio 87,9 con tunnel e 91,4 con onlay; nuova uscita della rotula 2,0% e 1,7%. Gli intervalli di incertezza si sovrappongono. L'onlay riguarda 249 pazienti, il 6,1% del totale.", "Limite: sono gruppi di studi diversi messi accanto, non un confronto diretto, e l'abstract non descrive che studi siano. Gli autori: tecnica comparabile e alternativa sicura quando il tunnel non è possibile, non dimostrata migliore."], "pazienti": ["Quando la rotula esce spesso dalla sua sede si può ricostruire il legamento che la trattiene. Il legamento viene fissato all'osso della coscia, di solito con un piccolo tunnel. Una revisione di 80 studi su 4100 adulti ha guardato se fissarlo sulla superficie dell'osso, senza tunnel, dia risultati simili.", "Nei due gruppi di studi il punteggio di funzione del ginocchio e la frequenza con cui la rotula è uscita di nuovo dalla sede sono risultati simili (2,0% con il tunnel, 1,7% senza), con ampi margini di incertezza.", "Il metodo senza tunnel riguarda pochi pazienti e gli studi non lo confrontano direttamente con l'altro. Non si può dire che sia migliore: può essere un'alternativa quando il tunnel non è possibile. La scelta spetta al chirurgo."]}, "instagram": {"chir": ["MPFL: onlay o tunnel sul femore?\nRevisione sistematica, The Knee 2026: 80 studi, 4100 adulti. Kujala 91,4 con onlay, 87,9 con tunnel; ridislocazione 1,7% contro 2,0%.", "Intervalli sovrapposti, onlay su soli 249 pazienti (6,1%), confronto indiretto. Comparabile, non superiore.", "Alternativa plausibile quando il tunnel non è possibile.\nFonte: PubMed, PMID 42790393."], "misto": ["Rotula instabile: il legamento che la trattiene si può fissare al femore anche senza tunnel?\nUna revisione di 80 studi su 4100 adulti: risultati simili.", "Punteggio del ginocchio 91,4 senza tunnel, 87,9 con tunnel; nuova uscita della rotula 1,7% contro 2,0%. Gli intervalli si sovrappongono.", "Limite: la fissazione senza tunnel riguarda solo 249 persone e i gruppi non sono confrontati direttamente.\nFonte: PubMed, PMID 42790393."], "pazienti": ["Rotula che esce dalla sede: il legamento che la trattiene si può ricostruire.\nUna revisione di 80 studi su 4100 adulti ha confrontato due modi di fissarlo all'osso della coscia.", "I risultati sono simili: la rotula è uscita di nuovo dalla sede nel 2,0% dei casi con il tunnel e nell'1,7% senza.", "Il metodo senza tunnel è stato usato su pochi pazienti: non si può dire che sia migliore. La scelta spetta al chirurgo.\nFonte: PubMed, PMID 42790393."]}, "reel": {"chir": ["Rotula instabile: tunnel o onlay sul femore?", "Ottanta studi, 4100 adulti: Kujala 91,4 contro 87,9, ridislocazione 1,7% contro 2,0%.", "Intervalli sovrapposti, onlay su 249 pazienti: comparabile, non superiore."], "misto": ["Rotula instabile: il legamento si può fissare senza tunnel?", "Ottanta studi, 4100 adulti: risultati simili, rotula uscita di nuovo nell'1,7% contro il 2,0%.", "Pochi casi senza tunnel: alternativa, non dimostrata migliore."], "pazienti": ["Rotula che esce dalla sede: serve sempre un tunnel?", "Una revisione di ottanta studi: risultati simili con i due metodi.", "Il metodo senza tunnel ha pochi dati; decide il chirurgo."]}}};
