var NLB={"1": {"prof": ["MPFL: la fissazione femorale onlay appare comparabile al tunnel osseo, su 249 pazienti", "Una revisione sistematica di 80 studi (The Knee, settembre 2026) su 4100 adulti operati di sola ricostruzione del MPFL riporta un Kujala medio di 91,4 (IC 95% 88,6-94,1) con fissazione onlay e di 87,9 (86,7-89,0) con tunnel osseo; ridislocazione 1,7% (0,47-3,78) contro 2,0% (1,3-2,9). Gli intervalli si sovrappongono e l'onlay riguarda il 6,1% dei pazienti. Gli autori la indicano come alternativa sicura quando i tunnel non sono possibili.", "Nota critica: confronto indiretto fra gruppi di studi diversi, senza aggiustamento per anatomia o follow-up; disegno degli 80 studi e rischio di bias non riportati nell'abstract; comparabile non significa superiore."], "mix": ["Rotula instabile: fissare il legamento al femore senza tunnel dà risultati simili", "Una revisione di 80 studi su 4100 adulti operati solo del legamento che trattiene la rotula (il legamento femororotuleo mediale) confronta la fissazione sull'osso con tunnel e quella sulla superficie dell'osso, senza tunnel. Il punteggio del ginocchio è 87,9 con il tunnel e 91,4 senza; la rotula esce di nuovo dalla sede nel 2,0% e nell'1,7% dei casi, con intervalli di incertezza che si sovrappongono.", "Nota sul limite: il metodo senza tunnel riguarda solo 249 persone e i due metodi non sono confrontati direttamente; gli autori lo ritengono un'alternativa sicura, non dimostrata migliore."], "paz": ["Rotula che esce dalla sede: il legamento si può fissare in due modi con risultati simili", "Quando la rotula esce più volte dalla sua sede, si può ricostruire il legamento che la trattiene e fissarlo all'osso della coscia, di solito con un piccolo tunnel. Una revisione di 80 studi su 4100 adulti ha guardato se fissarlo sulla superficie dell'osso, senza tunnel, dia risultati simili: in entrambi i casi la rotula è uscita di nuovo dalla sede in circa due casi su cento.", "Il metodo senza tunnel è stato usato su pochi pazienti e gli studi non lo confrontano direttamente con l'altro; la scelta spetta al chirurgo, caso per caso."], "kw": "instabilità rotulea, legamento femororotuleo mediale, rotula che esce dalla sede"}, "2": {"prof": ["LCA e angolo postero-laterale con un solo tunnel femorale: nota di tecnica con retto femorale", "Una nota di tecnica (Arthroscopy Techniques, settembre 2026) descrive la ricostruzione combinata del LCA e dell'angolo postero-laterale con un tunnel femorale condiviso e due autoinnesti: il retto femorale per il LCA e il tendine popliteo, il semitendinoso per il collaterale fibulare e il legamento popliteo-fibulare. Gli autori la presentano come riproducibile e capace di ridurre il rischio di convergenza dei tunnel.", "Nota critica: livello V, nessun paziente, nessun esito né follow-up; la riduzione del rischio di convergenza non è misurata nell'abstract."], "mix": ["Crociato e angolo postero-laterale ricostruiti insieme con un solo tunnel nel femore", "Una nota di tecnica chirurgica descrive come ricostruire insieme il legamento crociato anteriore e le strutture dell'angolo postero-laterale del ginocchio usando un solo tunnel nell'osso della coscia e due tendini prelevati dallo stesso paziente, uno dal muscolo retto femorale e uno dagli ischiocrurali. Gli autori sostengono che la soluzione riduce il rischio che i tunnel si incrocino.", "Nota sul limite: è la descrizione di una procedura, senza pazienti né risultati; non dice se funzioni meglio di altre."], "paz": ["Una tecnica per ricostruire più legamenti del ginocchio con un solo tunnel nell'osso", "Alcuni infortuni gravi del ginocchio danneggiano più legamenti insieme. Un articolo di tecnica chirurgica descrive come ricostruire il legamento crociato anteriore e le strutture della parte esterna e posteriore del ginocchio usando un solo tunnel nell'osso della coscia e due tendini prelevati dalla stessa persona.", "L'articolo descrive la procedura ma non riporta pazienti né risultati: non permette di dire quanto funzioni."], "kw": "lesione multilegamentosa ginocchio, ricostruzione crociato, angolo postero-laterale"}, "3": {"prof": ["LCA più legamento anterolaterale con hamstring aumentato da uno scaffold bioinduttivo: nota di tecnica", "Una nota di tecnica (Arthroscopy Techniques, ottobre 2026) descrive la ricostruzione combinata del LCA e del legamento anterolaterale con autoinnesto di gracile e semitendinoso aumentato con BioBrace, uno scaffold bioinduttivo rinforzato, per i pazienti piccoli in cui diametro e lunghezza dell'hamstring possono non bastare. Gli autori attribuiscono all'aumento maggiore spessore e resistenza senza morbilità aggiuntiva del sito donatore.", "Nota critica: livello V, nessun paziente né follow-up; spessore e resistenza non sono misurati nell'abstract; prodotto commerciale, conflitti di interesse non letti."], "mix": ["Crociato e legamento anterolaterale: come rinforzare un tendine troppo sottile", "Quando una persona di piccola taglia ha tendini troppo sottili o corti per ricostruire sia il legamento crociato anteriore sia un legamento laterale del ginocchio, gli autori di una nota di tecnica propongono di rinforzare il tendine con una membrana biologica di sostegno. Descrivono la procedura passo per passo, senza riportare pazienti.", "Nota sul limite: non ci sono risultati, quindi non si sa se la soluzione renda l'operazione più sicura o più efficace."], "paz": ["Una tecnica per rinforzare il tendine usato nella ricostruzione del legamento crociato", "Nella ricostruzione del legamento crociato anteriore si usa un tendine prelevato dalla stessa persona. Quando il tendine è troppo sottile, un articolo di tecnica propone di rinforzarlo con una membrana di sostegno, in modo da poter ricostruire anche un legamento sul lato del ginocchio.", "L'articolo descrive la tecnica ma non riporta pazienti né risultati: non si può dire se sia utile."], "kw": "ricostruzione crociato anteriore, legamento anterolaterale, instabilità del ginocchio"}, "4": {"prof": ["Collaterale mediale: il rerouting del semitendinoso stabilizza a 12 mesi anche nelle multilegamentose", "Una serie prospettica di 30 ricostruzioni del collaterale mediale con rerouting del semitendinoso (12 lesioni isolate e 18 multilegamentose) riporta, a 12 mesi, miglioramento significativo di stabilità in valgo e IKDC in entrambi i gruppi, con IKDC postoperatorio simile (p=0,602) e apertura in valgo ancora lievemente maggiore nelle multilegamentose (p<0,001); complicanze più frequenti nelle multilegamentose, nessun fallimento dell'innesto.", "Nota critica: 30 casi in un centro, senza confronto con altre tecniche; con 0 fallimenti su 30 il limite superiore del tasso è circa il 10%; valori assoluti e intervalli non riportati."], "mix": ["Legamento collaterale mediale: ricostruirlo con un tendine spostato dà stabilità a un anno", "In 30 persone operate di ricostruzione del legamento collaterale mediale con un tendine degli ischiocrurali spostato nella sede del legamento, 12 con lesione isolata e 18 con più legamenti danneggiati, a un anno il ginocchio è risultato più stabile e il punteggio funzionale è migliorato in entrambi i gruppi. Nelle lesioni con più legamenti la stabilità resta un po' peggiore e le complicanze sono state più frequenti.", "Nota sul limite: serie piccola, senza confronto con altre tecniche e con un solo anno di osservazione."], "paz": ["Ricostruzione del legamento collaterale mediale: risultati a un anno in 30 pazienti", "Il legamento collaterale mediale stabilizza il ginocchio dal lato interno. In 30 persone operate con un tendine prelevato dalla stessa gamba, a un anno il ginocchio era più stabile e il punteggio di funzione migliorato, sia con la lesione isolata sia con più legamenti danneggiati. Con più legamenti coinvolti le complicanze sono state più frequenti.", "Lo studio è piccolo, senza confronto con altre tecniche e dura un solo anno: i risultati vanno letti con prudenza."], "kw": "legamento collaterale mediale ricostruzione, lesione multilegamentosa, instabilità in valgo"}, "5": {"prof": ["Osteotomia tibiale d'apertura mediale: buoni esiti a 24 mesi anche con artrosi KL3, in 15 pazienti", "In una coorte retrospettiva di 73 osteotomie tibiali alte d'apertura mediale (58 KL1-2, 15 KL3), a 24 mesi la riduzione della VAS è maggiore nel gruppo KL3 (6,40±1,06 contro 4,47±1,52; p<0,001) e il guadagno KOOS è simile (32,8±8,9 contro 32,3±6,0; p=0,85); sopravvivenza libera da protesi 96,0% e reintervento per complicanze 12,3%.", "Nota critica: gruppo KL3 di 15 pazienti, follow-up di 24 mesi troppo breve per l'osteotomia, retrospettivo e non randomizzato; slope e fissazione non riportate nell'abstract."], "mix": ["Osteotomia del ginocchio: a due anni il dolore cala anche con artrosi moderata", "In 73 persone operate di osteotomia tibiale per correggere l'asse della gamba, a due anni il dolore è sceso e la funzione è migliorata sia con artrosi lieve sia con artrosi moderata; chi partiva dall'artrosi moderata (15 persone) ha avuto un calo del dolore maggiore. Il 96% non aveva ancora bisogno di una protesi, ma il 12,3% ha avuto una complicanza che ha richiesto un nuovo intervento.", "Nota sul limite: due anni sono pochi per un'operazione che si giudica a cinque-dieci anni, e il gruppo con artrosi moderata è piccolo."], "paz": ["Osteotomia del ginocchio: miglioramento a due anni anche con artrosi moderata", "L'osteotomia corregge l'asse della gamba per scaricare la parte del ginocchio più consumata. In uno studio su 73 persone, a due anni il dolore era diminuito e la funzione migliorata sia con artrosi lieve sia con artrosi moderata. In circa un caso su otto è stato necessario un nuovo intervento per una complicanza.", "Lo studio è piccolo e segue i pazienti solo per due anni: non dice come andranno negli anni successivi."], "kw": "osteotomia tibiale alta, artrosi ginocchio, ritardare la protesi"}, "6": {"prof": ["MOBCART: un punteggio RM per l'osso dopo ricostruzione osteocondrale, ICC 0,72 fra i lettori", "Il punteggio MOBCART (Integrazione, Normalizzazione, Cisti; 0-50) è proposto come aggiunta al MOCART 2.0 per la componente ossea dopo ricostruzione osteocondrale del ginocchio. Su 32 RM di 23 pazienti e quattro lettori, l'ICC del totale è 0,72 fra tutti i lettori e 0,90 fra gli esperti; l'ICC intra-lettore è 0,98 e 0,85. Giuseppe Filardo è fra gli autori.", "Nota critica: misura la ripetibilità, non la relazione con dolore, funzione o fallimento; intervalli degli ICC non riportati; tecnica di ricostruzione non descritta."], "mix": ["Risonanza dopo ricostruzione della cartilagine: un punteggio per giudicare l'osso, ripetibile fra lettori", "Un gruppo internazionale propone un punteggio da risonanza magnetica per descrivere l'osso sotto la cartilagine riparata, in aggiunta al punteggio già in uso. Quattro lettori, fra cui esperti e medici in formazione, hanno letto 32 risonanze di 23 pazienti: l'accordo è risultato buono fra gli esperti e meno alto fra tutti i lettori.", "Nota sul limite: il punteggio dice quanto i lettori concordano, non se predica l'esito del paziente."], "paz": ["Risonanza dopo la riparazione della cartilagine: un nuovo modo di descrivere l'osso", "Dopo certe riparazioni della cartilagine del ginocchio, la risonanza magnetica mostra anche come guarisce l'osso sotto la cartilagine. Un gruppo di specialisti propone un punteggio per descriverlo sempre con le stesse regole e ha verificato che diversi lettori arrivino a valutazioni simili.", "Lo studio verifica l'accordo fra i lettori, non se il punteggio aiuti a prevedere come starà il paziente."], "kw": "riparazione cartilagine ginocchio, risonanza magnetica, ricostruzione osteocondrale"}, "7": {"prof": ["Menisco laterale ipermobile: indice diagnostico con AUC 0,84, validazione solo interna", "In 100 pazienti consecutivi con sospetta patologia meniscale laterale, l'ipermobilità confermata in artroscopia dinamica era presente nel 47%. Un indice a cinque predittori clinici e RM dà AUC 0,84 (IC riportato 0,83-0,95), sensibilità 81%, specificità 79,2% con soglia ≥5 punti; AUC corretta per ottimismo 0,82 (J ISAKOS, settembre 2026).", "Nota critica: un centro, validazione interna, intervallo dell'AUC non centrato sul valore puntuale; serve la validazione esterna prima dell'uso di routine."], "mix": ["Menisco laterale che si muove troppo: un punteggio per riconoscerlo prima dell'artroscopia", "Il menisco laterale ipermobile è difficile da vedere in risonanza. In 100 pazienti operati, un punteggio che unisce blocco intermittente, un test clinico e due segni della risonanza ha riconosciuto il problema in circa quattro casi su cinque; dei pazienti con il punteggio positivo, circa uno su cinque non lo aveva.", "Nota sul limite: è stato provato in un solo centro e sugli stessi pazienti su cui è stato costruito; serve una conferma esterna."], "paz": ["Menisco laterale ipermobile: un punteggio per aiutare a riconoscerlo", "Il menisco è una struttura di cartilagine che ammortizza il ginocchio. In alcune persone quello esterno si muove troppo e può dare blocchi o scatti. Un gruppo di chirurghi ha costruito un punteggio che unisce i sintomi e la risonanza per sospettarlo prima dell'artroscopia.", "Il punteggio è stato provato su 100 pazienti in un solo centro e non sostituisce la valutazione del chirurgo."], "kw": "menisco laterale, blocco del ginocchio, artroscopia ginocchio"}, "8": {"prof": ["LCA con hamstring: bottone corticale contro vite con graffa, nessun vantaggio netto su 58 pazienti", "In una coorte retrospettiva bicentrica di 58 ricostruzioni del LCA con hamstring (26 bottone, 32 vite bioassorbibile più graffa) il dolore del sito donatore è più alto con il bottone (VAS mediana 2,5 contro 2,0; p=0,007) e l'IKDC più alto con la graffa (71,0 contro 60,0; p=0,017); Lysholm, ROM, stabilità e fallimento (11,5% contro 18,8%; p=0,495) non differiscono in modo significativo.", "Nota critica: gruppi assegnati dal diametro dell'innesto, quindi confusi; fallimenti 3 contro 6 (RR 0,62, IC 95% 0,17-2,23); solo hamstring, follow-up minimo 12 mesi."], "mix": ["Crociato: due modi di fissare il tendine alla tibia, nessuno chiaramente migliore", "Su 58 persone operate di ricostruzione del crociato con tendini degli ischiocrurali, due modi di fissare il tendine alla tibia hanno dato risultati simili su stabilità, movimento e nuove rotture. Con il bottone il dolore nel punto di prelievo è stato un po' più alto; con la vite e la graffa il punteggio funzionale è stato più alto.", "Nota sul limite: i due gruppi non erano scelti a caso ma dal diametro del tendine, e i numeri sono piccoli."], "paz": ["Ricostruzione del crociato: due modi di fissare il tendine, risultati simili", "Nella ricostruzione del legamento crociato anteriore il tendine va fissato all'osso della tibia, e si può fare in modi diversi. Su 58 persone, due metodi hanno dato risultati simili per stabilità, movimento e nuove rotture; il dolore nel punto di prelievo è stato un po' più alto con uno dei due.", "Lo studio è piccolo e i pazienti non sono stati assegnati a caso: non permette di dire quale metodo sia migliore."], "kw": "ricostruzione crociato anteriore, fissazione tendine, dolore sito di prelievo"}, "9": {"prof": ["Revisioni di protesi di ginocchio: proiezione a +41% entro il 2060 in 17 paesi, con forbice fra modelli", "Una proiezione da dati di registro di 17 paesi (JBJS, settembre 2026) stima nel 2024 189.689 revisioni di protesi di ginocchio e 185.921 d'anca; al 2060, nel modello primario, 267.456 (+41%) e 243.404 (+31%). I quattro modelli di sensibilità danno 461.000-511.000 revisioni combinate nel 2060; Stati Uniti e Cina spiegano la maggior parte della crescita.", "Nota critica: è una proiezione che assume la continuità dei trend (limitati a ±2,0% e smorzati); registri eterogenei; intervalli di confidenza non riportati; Svizzera non nominata nell'abstract."], "mix": ["Protesi di ginocchio e d'anca: le revisioni potrebbero crescere di circa un terzo entro il 2060", "Una stima basata sui registri di 17 paesi prevede che le operazioni per sostituire o correggere una protesi già impiantata passino, per il ginocchio, da circa 190.000 nel 2024 a circa 267.000 nel 2060 (+41%), e per l'anca da circa 186.000 a circa 243.000 (+31%). La crescita più forte è attesa negli Stati Uniti e in Cina; alcuni paesi europei e il Giappone tendono a stabilizzarsi o a calare.", "Nota sul limite: è una previsione e non una misura; modelli diversi danno cifre diverse, con una forbice di circa 50.000 interventi nel 2060."], "paz": ["Protesi del ginocchio: nel mondo le operazioni di revisione aumenteranno nei prossimi decenni", "Con sempre più protesi di ginocchio e d'anca impiantate, aumenta anche il numero di persone che negli anni successivi hanno bisogno di una nuova operazione sulla protesi. Una stima su 17 paesi prevede entro il 2060 un aumento di circa il 41% per il ginocchio.", "È una previsione basata su modelli e su ipotesi, non una misura; non dice nulla sul rischio di una singola persona."], "kw": "revisione protesi ginocchio, registro protesi, protesi totale ginocchio"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"The Knee",h:"MPFL: la fissazione onlay sul femore appare comparabile al tunnel osseo",v:"Revisione sistematica di 80 studi su 4100 adulti operati di sola ricostruzione del MPFL: Kujala medio 91,4 con onlay contro 87,9 con tunnel, ridislocazione 1,7% contro 2,0%, con intervalli che si sovrappongono. L'onlay è il 6,1% dei pazienti: confronto indiretto, non un paragone diretto.",ax:"Nam, Velasquez-Hammerle, Merkely, Leite, Nakanishi, Nagai, Nukala, Matsushita, Kuroda, Tanaka",date:"set 2026",meta:"revisione sistematica, 80 studi, 4100 pazienti (tunnel 3851, onlay 249), MPFL isolato in adulti scheletricamente maturi · [I]",pmid:'42790393',doi:'10.1016/j.knee.2026.104613',journal:"The Knee",authors:"Nam HH, Velasquez-Hammerle MV, Merkely G, Leite CBG, Nakanishi Y, Nagai K, Nukala V, Matsushita T, Kuroda R, Tanaka MJ",design:"Revisione sistematica con ricerca nella letteratura a maggio 2026 su studi di ricostruzione isolata del MPFL per instabilità femororotulea in adulti scheletricamente maturi, con tecnica, complicanze e ricorrenza. Esclusi: chirurgia omolaterale precedente, procedure concomitanti, riparazioni del MPFL, malattie congenite, case report, campioni sotto 10. Obiettivo: soddisfazione e successo della fissazione femorale con tunnel osseo e con onlay. Metodo di sintesi, valutazione del rischio di bias e disegno degli 80 studi non riportati nell'abstract.",pop:"80 studi, 4100 pazienti (60,8% donne, 39,2% uomini): 3851 (93,9%) con tunnel osseo femorale, 249 (6,1%) con fissazione onlay.",results:"Kujala medio postoperatorio 87,9 (IC 95% 86,7-89,0) con tunnel e 91,4 (IC 95% 88,6-94,1) con onlay. Ridislocazione media 2,0% (IC 95% 1,3-2,9) con tunnel e 1,7% (IC 95% 0,47-3,78) con onlay. Gli intervalli si sovrappongono sia sul Kujala sia sulla ridislocazione; nessun confronto diretto fra i gruppi (differenza con intervallo, p) riportato nell'abstract.",concl:"Gli autori: la fissazione onlay è molto meno riportata ma appare comparabile al tunnel osseo, con buoni esiti e bassa ridislocazione; può essere considerata un'alternativa sicura quando i tunnel non sono possibili.",limits:"Onlay su 249 pazienti contro 3851: la stima è molto meno precisa (l'intervallo della ridislocazione arriva a 3,78%) · confronto indiretto fra gruppi di studi diversi, senza aggiustamento per indicazione, anatomia (displasia trocleare, altezza rotulea) o follow-up, non riportati nell'abstract · composizione degli 80 studi (serie di casi o comparativi) e rischio di bias non riportati · testo completo non disponibile su PMC: numeri dall'abstract, non dal testo.",perte:"Non risulta dai tuoi documenti quale fissazione femorale usi per il MPFL (è fra i tuoi temi). Se usi il tunnel: la revisione dice che l'onlay è un'alternativa plausibile, non dimostrata migliore. Se usi già l'onlay: 249 pazienti sono pochi per confermare la scelta. Esclusi i casi con procedure concomitanti e gli scheletricamente immaturi: non descrive i casi complessi. Non muove nessuna tensione."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy Techniques",h:"LCA e angolo postero-laterale con un solo tunnel femorale e retto femorale",v:"Nota di tecnica: un tunnel femorale condiviso per LCA e angolo postero-laterale; il retto femorale serve per il LCA e per il tendine popliteo, il semitendinoso per il collaterale fibulare e il legamento popliteo-fibulare. Nessun dato clinico: descrive, non dimostra.",ax:"de Oliveira Paolucci, Gomes Gobbi, de Fava Sanches, El Orra, Schuwarten Aidar",date:"set 2026",meta:"nota di tecnica chirurgica (Arthroscopy Techniques), nessun paziente riportato nell'abstract · [V]",pmid:'42799422',doi:'10.1002/atn2.70275',journal:"Arthroscopy Techniques",authors:"de Oliveira Paolucci PH, Gomes Gobbi R, de Fava Sanches F, El Orra S, Schuwarten Aidar R",design:"Nota di tecnica: ricostruzione combinata del LCA e dell'angolo postero-laterale con un solo tunnel femorale e due autoinnesti, retto femorale e semitendinoso. Una parte di entrambi gli innesti è preparata per il LCA anatomico; il tunnel condiviso ha un'uscita laterale per la fissazione prossimale dell'angolo; il retto femorale residuo ricostruisce il tendine popliteo, il semitendinoso residuo il legamento collaterale fibulare e il popliteo-fibulare.",pop:"Nessuna popolazione: la nota non riporta pazienti nell'abstract.",results:"Nessun risultato clinico, radiologico o biomeccanico nell'abstract. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori la presentano come tecnica riproducibile, su basi anatomiche, che permette la ricostruzione combinata con un solo tunnel femorale e riduce il rischio di convergenza dei tunnel.",limits:"Livello V: nessun paziente, nessun esito, nessun follow-up · «riduce il rischio di convergenza dei tunnel» è un'affermazione degli autori, non misurata nell'abstract · l'abstract non dice in quanti casi sia stata usata né con quali complicanze · testo completo ad accesso aperto su PMC (PMC13614089) non aperto oggi: solo l'abstract.",perte:"Usa il retto femorale, il tuo innesto, in un contesto multilegamentoso (LCA più angolo postero-laterale), che è uno dei tuoi temi. È una descrizione di tecnica, non un'evidenza: serve come idea di costrutto a tunnel unico da confrontare con le tue tecniche; non dà dati su stabilità né su fallimenti. Non muove T1: nessun rinforzo laterale extra-articolare."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy Techniques",h:"LCA più legamento anterolaterale con hamstring aumentato da uno scaffold bioinduttivo",v:"Nota di tecnica per i pazienti di piccola taglia, in cui l'hamstring può non bastare per la procedura combinata: gli autori aumentano l'innesto con BioBrace, uno scaffold bioinduttivo rinforzato. Nessun dato clinico: le affermazioni su spessore e resistenza non sono misurate.",ax:"Wong, Lai, Wan, Lee, Ng",date:"ott 2026",meta:"nota di tecnica chirurgica (Arthroscopy Techniques), nessun paziente riportato nell'abstract · [V]",pmid:'42825213',doi:'10.1002/atn2.70315',journal:"Arthroscopy Techniques",authors:"Wong CW, Lai CY, Wan KH, Lee RH, Ng EP",design:"Nota di tecnica: ricostruzione combinata del LCA e del legamento anterolaterale (ALL) con autoinnesto di gracile e semitendinoso aumentato con BioBrace, uno scaffold bioinduttivo rinforzato. Indicazione dichiarata: rottura del LCA con instabilità rotatoria preoperatoria; il problema è che nei pazienti piccoli diametro e lunghezza dell'hamstring possono non bastare per la procedura combinata.",pop:"Nessuna popolazione: la nota non riporta pazienti nell'abstract.",results:"Nessun risultato clinico, di imaging o biomeccanico riportato: l'abstract attribuisce allo scaffold un aumento di spessore e di resistenza biomeccanica dell'innesto senza morbilità aggiuntiva del sito donatore, ma senza dati. Dimensioni dell'effetto e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori descrivono la procedura combinata con aumento dell'innesto come soluzione quando l'hamstring autologo da solo non basta.",limits:"Livello V: nessun paziente, nessun follow-up · l'aumento di spessore e di resistenza è un'affermazione degli autori, non misurata nell'abstract · prodotto commerciale: eventuali conflitti di interesse non letti · testo completo su PMC (PMC13629731) non aperto oggi.",perte:"Il rinforzo laterale che usi è il Lemaire onlay su tendine quadricipitale/retto femorale; qui l'alternativa è la ricostruzione del legamento anterolaterale su hamstring, un'altra via per la stessa indicazione di instabilità rotatoria. Nessun confronto fra le due, nessun dato sul tuo innesto: non muove T1a. Resta come descrizione di una soluzione per innesti troppo corti."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Annals of African Medicine",h:"Collaterale mediale: il rerouting del semitendinoso stabilizza anche nelle multilegamentose",v:"Serie prospettica di 30 ricostruzioni del collaterale mediale con rerouting del semitendinoso (12 lesioni isolate, 18 multilegamentose): a 12 mesi stabilità in valgo e IKDC migliorano in entrambi i gruppi, IKDC simile (p=0,602); più complicanze nelle multilegamentose, nessun fallimento dell'innesto.",ax:"Deshmukh, Solunke, Sethi, Nair, Kulkarni",date:"set 2026",meta:"serie prospettica, 30 pazienti (12 collaterale mediale isolato, 18 multilegamentosi), follow-up minimo 12 mesi · [IV]",pmid:'42813979',doi:'10.4103/aam.aam_692_26',journal:"Annals of African Medicine",authors:"Deshmukh A, Solunke S, Sethi A, Nair A, Kulkarni K",design:"Studio di coorte prospettico in un ospedale universitario terziario (novembre 2022-novembre 2024): 30 pazienti con ricostruzione del collaterale mediale mediante rerouting del tendine semitendinoso, seguiti per almeno 12 mesi. Valutazione con test da stress in valgo e punteggio IKDC; confronto fra lesioni isolate di grado III e multilegamentose con collaterale mediale di grado III.",pop:"30 pazienti: 12 con rottura isolata di grado III del collaterale mediale, 18 con lesione multilegamentosa e collaterale mediale di grado III. Età, sesso e legamenti associati non riportati nell'abstract.",results:"Apertura in valgo preoperatoria maggiore nel gruppo multilegamentoso (p<0,001), IKDC preoperatorio simile (p=0,848). A 12 mesi miglioramento significativo di stabilità e funzione in entrambi i gruppi; apertura in valgo postoperatoria ancora lievemente maggiore nel gruppo multilegamentoso (p<0,001), IKDC postoperatorio simile (p=0,602). Miglioramento percentuale della stabilità in valgo 81,82% in entrambi i gruppi. Complicanze più frequenti nel gruppo multilegamentoso, nessun fallimento dell'innesto. Valori assoluti di apertura e IKDC, numero e tipo di complicanze e intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: il rerouting del semitendinoso ripristina la stabilità mediale con esiti funzionali comparabili fra lesioni isolate e multilegamentose; tecnica affidabile ed economica, con impianti minimi.",limits:"Serie di 30 casi in un centro, senza confronto con altre tecniche di ricostruzione del collaterale mediale · follow-up minimo 12 mesi: nulla sul lungo termine · valori assoluti, complicanze e intervalli non sono nell'abstract · «economica» è una conclusione sul costo non misurata nell'abstract.",perte:"Multilegamentose è fra i tuoi temi. Il rerouting dell'ischiocrurale è una tecnica a innesto singolo con impianti minimi: non dà indicazioni sul tuo costrutto con retto femorale/tendine quadricipitale. Utile per un dato: nelle multilegamentose la stabilità in valgo resta un po' peggiore che nel collaterale isolato, pur con funzione simile. Non muove tensioni."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Sisli Etfal Hastanesi Tip Bulteni",h:"Osteotomia tibiale d'apertura mediale: buoni esiti a 24 mesi anche con artrosi KL3",v:"Coorte retrospettiva di 73 osteotomie (58 KL1-2, 15 KL3): a 24 mesi il dolore scende di più nel gruppo KL3 (ΔVAS 6,40±1,06 contro 4,47±1,52; p<0,001) e il KOOS migliora in modo simile (p=0,85). Sopravvivenza libera da protesi a 24 mesi 96,0%; reintervento per complicanze 12,3%.",ax:"Altuntas, Ipek, Armagan, Alibakan, Demirkale, Eren",date:"set 2026",meta:"coorte retrospettiva monocentrica, 73 pazienti (KL1-2 58, KL3 15), follow-up 24 mesi · [IV]",pmid:'42824906',doi:'10.14744/SEMB.2026.25936',journal:"Sisli Etfal Hastanesi Tip Bulteni",authors:"Altuntas Y, Ipek E, Armagan R, Alibakan G, Demirkale I, Eren OT",design:"Studio osservazionale retrospettivo su 73 adulti consecutivi operati di osteotomia tibiale alta d'apertura mediale biplanare (maggio 2020-maggio 2023) in un centro terziario, stratificati per grado di Kellgren-Lawrence: KL1-2 (n=58) e KL3 (n=15). VAS, KOOS e WOMAC a 6, 12 e 24 mesi; parametri di allineamento radiografico e complicanze registrati.",pop:"73 adulti consecutivi, un solo centro terziario: 58 con artrosi KL1-2 e 15 con KL3. Età, sesso, entità della correzione e slope non riportati nell'abstract.",results:"VAS preoperatoria KL1-2 7,79±0,89 e KL3 8,27±0,70 (p=0,066); a 24 mesi 3,33±1,15 e 1,87±0,74; riduzione ΔVAS 4,47±1,52 contro 6,40±1,06 (p<0,001, a favore di KL3). KOOS da 53,1±8,2 a 85,4±5,8 (KL1-2) e da 43,9±7,6 a 76,7±6,3 (KL3); ΔKOOS 32,3±6,0 contro 32,8±8,9 (p=0,85). WOMAC ΔKL3 26,5±8,2 contro 21,2±7,4 (p=0,034). Complicanze con reintervento 12,3%; sopravvivenza libera da protesi a 24 mesi 96,0%. Intervalli di confidenza non riportati nell'abstract.",concl:"Gli autori: l'osteotomia d'apertura mediale dà un miglioramento significativo di dolore e funzione a breve termine in tutti i gradi, e i pazienti KL3 ottengono un sollievo comparabile o maggiore nonostante lo stato di partenza peggiore; opzione valida in pazienti selezionati con artrosi moderata per ritardare la protesi.",limits:"Gruppo KL3 di 15 pazienti, con deviazioni standard molto diverse dal gruppo KL1-2 · follow-up di 24 mesi: troppo breve per un'operazione che si giudica a 5-10 anni · retrospettivo, non randomizzato: la selezione dei KL3 non è descritta nell'abstract · il maggior ΔVAS in KL3 parte da un dolore basale più alto.",perte:"Osteotomia è un tuo tema: a 24 mesi l'apertura mediale funziona anche con KL3 in pazienti selezionati. Nessun dato sulla slope né sulla tecnica di fissazione nell'abstract; non cambia la tua indicazione, ma sposta un poco il limite di grado in cui non scartare l'osteotomia. Non muove tensioni."},{n:6,mono:"m-gray",dot:"gray",sec:"res",j:"Insights into Imaging",h:"MOBCART: un punteggio RM per l'osso dopo ricostruzione osteocondrale del ginocchio",v:"Studio di riproducibilità su 32 RM di 23 pazienti, quattro lettori: ICC del punteggio totale 0,72 fra tutti i lettori, 0,90 fra gli esperti; la concordanza intra-lettore arriva a 0,98 e 0,85. Giuseppe Filardo è fra gli autori. Misura la ripetibilità, non l'esito clinico.",ax:"Koenig, Schreiner, Szomolanyi, Juras, Raudner, Sorgo, Wollner, Filardo, Winalski, Guermazi, Bugbee, Trattnig",date:"set 2026",meta:"studio di riproducibilità, 32 RM da 23 pazienti, 4 lettori · [IV]",pmid:'42811246',doi:'10.1186/s13244-026-02404-3',journal:"Insights into Imaging",authors:"Koenig FRM, Schreiner M, Szomolanyi P, Juras V, Raudner M, Sorgo P, Wollner G, Filardo G, Winalski CS, Guermazi A, Bugbee WD, Trattnig S",design:"Introduce il punteggio MOBCART (Integrazione, Normalizzazione, Cisti; 0-50 punti) come componente aggiuntiva dello score MOCART 2.0 del ginocchio, per valutare con la risonanza la componente ossea dopo ricostruzione osteocondrale. 32 RM postoperatorie lette da quattro lettori indipendenti (radiologo muscoloscheletrico esperto, specialista ortopedico della cartilagine esperto, un radiologo e un ortopedico in formazione); due lettori hanno ripetuto la lettura. Affidabilità con kappa pesato per i domini e ICC per il totale.",pop:"32 risonanze postoperatorie di 23 pazienti dopo ricostruzione osteocondrale del ginocchio. Tecnica di ricostruzione, età e tempo dall'intervento non riportati nell'abstract.",results:"Affidabilità inter-lettore sul totale ICC(A,1) 0,72 (da moderata a buona), kappa dei domini 0,71-0,82. Concordanza fra i lettori esperti ICC 0,90, kappa 0,93-0,95. Affidabilità intra-lettore: ICC 0,98 (lettore 1) e 0,85 (lettore 4). Intervalli di confidenza degli ICC non riportati nell'abstract.",concl:"Gli autori: il MOBCART è un supplemento riproducibile, centrato sull'osso, al MOCART 2.0 e permette un referto RM standardizzato delle caratteristiche ossee dopo ricostruzione osteocondrale.",limits:"Misura la ripetibilità fra lettori, non la correlazione con dolore, funzione o fallimento · 32 esami da 23 pazienti, intervalli degli ICC non riportati: l'ICC dei non esperti (0,72) è sensibilmente più basso di quello degli esperti (0,90) · tecnica e follow-up delle ricostruzioni non descritti nell'abstract.",perte:"Non è una tecnica ma uno strumento di misura: per valutare con la RM le riparazioni che fai o segui (AMIC, minced cartilage, ricostruzioni osteocondrali) il punteggio osseo si aggiunge al MOCART 2.0. Filardo (EOC Lugano/USI, tua rete) è fra gli autori: nome letto nei metadati PubMed. Non muove T5, che riguarda la tecnica e non la misura."},{n:7,mono:"m-gray",dot:"gray",sec:"res",j:"Journal of ISAKOS",h:"Menisco laterale ipermobile: un indice diagnostico che unisce clinica e risonanza",v:"Modello diagnostico su 100 pazienti consecutivi, standard di riferimento l'artroscopia dinamica: ipermobilità confermata nel 47%; AUC 0,84 (IC riportato 0,83-0,95), sensibilità 81%, specificità 79,2%, AUC corretta per ottimismo 0,82. Solo validazione interna.",ax:"Rivarola, Collazo, Palanconi, Meninato, Barros Castro, Peñaherrera-Carrillo, Endara Urresta",date:"set 2026",meta:"studio diagnostico retrospettivo, 100 pazienti consecutivi, centro terziario di chirurgia del ginocchio · [III]",pmid:'42800675',doi:'10.1016/j.jisako.2026.101227',journal:"Journal of ISAKOS",authors:"Rivarola H, Collazo C, Palanconi M, Meninato M, Barros Castro A, Peñaherrera-Carrillo C, Endara Urresta F",design:"Sviluppo e validazione interna di un modello diagnostico per il menisco laterale ipermobile: 100 pazienti consecutivi con sospetta patologia meniscale laterale, esame clinico standardizzato, RM preoperatoria e valutazione artroscopica dinamica della mobilità meniscale (standard di riferimento, non inserito nel modello). Predittori solo preoperatori (blocco intermittente, McMurray postero-laterale, gap meniscocapsulare, sospetta discontinuità meniscotibiale); regressione logistica penalizzata LASSO, indice a punti, validazione con bootstrap e simulazione Monte Carlo.",pop:"100 pazienti consecutivi, un centro terziario di chirurgia del ginocchio (Hospital Universitario Austral, Buenos Aires, primo affiliato; coautori anche a Quito). Età, sesso e lesioni associate non riportati nell'abstract.",results:"Menisco ipermobile confermato in artroscopia nel 47%. Cinque predittori nel modello finale; AUC 0,84 (IC 95% riportato 0,83-0,95: l'intervallo non è centrato sul valore, come scritto nell'abstract). Soglia ≥5 punti: sensibilità 81%, specificità 79,2%, VPP 77,6%, VPN 82,4%. Calibrazione: pendenza 0,94, intercetta 0,03, Brier 0,13. AUC corretta per ottimismo 0,82.",concl:"Gli autori: l'Hypermobile Meniscus Index offre un quadro strutturato per riconoscere prima dell'intervento il menisco laterale ipermobile e orientare la valutazione artroscopica mirata; serve la validazione esterna prima dell'uso di routine.",limits:"Validazione solo interna, un centro, 100 pazienti · standard di riferimento (mobilità in artroscopia dinamica) non dichiarato in cieco rispetto ai predittori nell'abstract · AUC con IC 0,83-0,95 attorno a 0,84: l'intervallo riportato è incoerente con il valore puntuale, da rileggere nel testo · sensibilità e specificità attorno all'80%: circa uno su cinque resta mal classificato.",perte:"Menisco laterale ipermobile: non è la tua radice meniscale, ma è una diagnosi che si perde se non la si cerca; il modello dice che cosa guardare prima dell'artroscopia (blocco intermittente, McMurray postero-laterale, gap meniscocapsulare). Non applicare a tappeto prima della validazione esterna. Non muove T3."},{n:8,mono:"m-gray",dot:"gray",sec:"res",j:"Medicina (Kaunas)",h:"LCA con hamstring: bottone corticale o vite bioassorbibile con graffa, nessun vantaggio netto",v:"Coorte retrospettiva bicentrica su 58 ricostruzioni (26 bottone, 32 vite più graffa): dolore del sito donatore più alto con il bottone (VAS mediana 2,5 contro 2,0; p=0,007), IKDC più alto con la graffa (71,0 contro 60,0; p=0,017); Lysholm, stabilità e fallimento senza differenze significative.",ax:"Polat, Koncalıoğlu, Kuyumcu, Akgün, Ziara, Artvin, Çınar, Topkar",date:"ago 2026",meta:"coorte retrospettiva comparativa bicentrica, 58 pazienti (26 contro 32), follow-up minimo 12 mesi · [III]",pmid:'42796236',doi:'10.3390/medicina62091629',journal:"Medicina (Kaunas)",authors:"Polat O, Koncalıoğlu B, Kuyumcu M, Akgün E, Ziara MNM, Artvin D, Çınar SM, Topkar OM",design:"Coorte retrospettiva comparativa su due centri: ricostruzione primaria isolata del LCA con autoinnesto di semitendinoso e gracile, fissazione tibiale con bottone corticale (innesto quadruplo più corto) oppure vite bioassorbibile con graffa a U (innesto doppio più lungo). L'assegnazione al gruppo dipendeva dal diametro iniziale dell'innesto, riportato nel referto operatorio. Dolore del sito donatore (VAS), diametro, IKDC, Lysholm, ROM, Lachman, pivot shift, fallimento (discontinuità alla RM con Lachman 2-3 o pivot positivo).",pop:"58 pazienti con lesione isolata del LCA, follow-up minimo 12 mesi: 26 con bottone corticale e 32 con vite più graffa. Età, sesso e follow-up medio non riportati nell'abstract.",results:"Dolore del sito donatore: VAS mediana 2,5 (2,0-4,0) con il bottone contro 2,0 (0-2,0) con la graffa (p=0,007). Diametro dell'innesto 10,0 mm contro 9,0 mm (p<0,001). IKDC mediano 71,0 (51,5-78,0) con la graffa contro 60,0 (55,0-62,8) con il bottone (p=0,017). Nessuna differenza per Lysholm (p=0,701), ROM (p=0,508), pivot positivo 11,5% contro 6,3% (p=0,648), Lachman rilevante 30,8% contro 18,8% (p=0,287), fallimento 11,5% contro 18,8% (p=0,495).",concl:"Gli autori: nessuna differenza significativa su Lysholm, ROM, stabilità clinica e fallimento; con la graffa meno dolore al sito donatore e IKDC più alto, con il bottone innesti di diametro maggiore, probabilmente per la configurazione quadrupla più corta; nessun vantaggio costante di un costrutto.",limits:"Gruppi assegnati dal diametro dell'innesto, non a caso: i due costrutti differiscono anche per innesto (quadruplo contro doppio), quindi il confronto è confuso · 58 pazienti, fallimenti 3 contro 6 · solo hamstring, nessun rinforzo laterale · follow-up minimo 12 mesi.",perte:"Fissazione tibiale dell'hamstring: non è il tuo innesto (usi retto femorale/tendine quadricipitale) né la tua fissazione. Dato utile solo come promemoria che, nei confronti retrospettivi di fissazione, il diametro dell'innesto e la lunghezza del costrutto confondono. Non muove tensioni."},{n:9,mono:"m-gray",dot:"gray",sec:"res",j:"The Journal of Bone and Joint Surgery",h:"Revisioni di protesi di ginocchio: proiezione a +41% entro il 2060 in 17 paesi",v:"Proiezione da registri di 17 paesi con un metodo uniforme: nel 2024 circa 189.689 revisioni di protesi di ginocchio e 185.921 d'anca; al 2060, nel modello primario, 267.456 (+41%) e 243.404 (+31%). I quattro modelli danno 461.000-511.000 revisioni combinate: la forbice è l'incertezza.",ax:"Adolf, Karlıdağ, Citak",date:"set 2026",meta:"modello di proiezione da dati di registro, 17 paesi, anca e ginocchio · [IV]",pmid:'42814846',doi:'10.2106/JBJS.26.00772',journal:"The Journal of Bone and Joint Surgery",authors:"Adolf J, Karlıdağ T, Citak M",design:"Stima uniforme dei volumi annui di revisione di protesi d'anca (rTHA) e di ginocchio (rTKA) al 2060 in 17 paesi con registro. Conteggi annui dall'ultimo rapporto di registro o da pubblicazioni basate su registro; denominatori demografici ONU (World Population Prospects 2024, variante media, adulti dai 25 anni). Per ogni paese e procedura, modello di Poisson log-lineare con anno come covariata e popolazione come offset, trend condiviso fra paesi, limitato a ±2,0% annuo e smorzato nell'orizzonte. Tre analisi di sensibilità (solo demografia, mezzo trend, saturazione logistica).",pop:"17 paesi dotati di registro (non elencati tutti nell'abstract: citati Stati Uniti, Cina, Germania, Regno Unito, Svezia, Giappone); la Svizzera non è nominata nell'abstract.",results:"Nel 2024 il totale modellato è 185.921 rTHA e 189.689 rTKA. Al 2060, modello primario: 243.404 rTHA e 267.456 rTKA, aumenti del 31% e 41% rispetto al 2024 (36% aggregato). I quattro metodi producono volumi combinati nel 2060 da circa 461.000 (solo demografia) a circa 511.000 (modello primario). Stati Uniti e Cina spiegano la maggior parte della crescita; Germania, Regno Unito e Svezia verso un plateau; Giappone in calo. Intervalli di confidenza non riportati nell'abstract: l'incertezza è espressa dalla forbice fra modelli.",concl:"Gli autori: i volumi di revisione cresceranno di circa un terzo entro il 2060 (36% in aggregato), con implicazioni per la formazione in chirurgia di revisione, la prevenzione delle infezioni e le infrastrutture dei registri.",limits:"Proiezione, non osservazione: dipende dall'ipotesi che i trend recenti proseguano (limitati a ±2,0% e smorzati) · dati eterogenei da registri diversi, copertura e definizioni di revisione non uniformi · forbice di circa 50.000 interventi fra i modelli · nessun dato svizzero nell'abstract.",perte:"Contesto, non pratica: dice dove andrà il carico della revisione protesica, non che cosa fare oggi nel tuo ambulatorio. Tocca soprattutto chi fa revisioni; per te vale come cornice per le tue protesi (VELYS) e per le infezioni. Non muove tensioni."}];
var SUGGQ=[{"k": "kol", "n": "T. Matsushita (Kobe University, Giappone)", "w": "Kobe University (Giappone) — coautore della revisione di oggi sulla fissazione onlay o a tunnel nel MPFL (PMID 42790393, afferenza letta nei metadati PubMed) e firmatario, con Kuroda R, dello studio biomeccanico su cadavere che confronta doppio fascio e fascio singolo più LET (PMID 42762098, già nello storico); corrispondenza tecnica con il tuo rinforzo laterale (LET) e con il MPFL. Colma il buco orientale dichiarato. Sostituisce Mario Hevesi (2 ottobre, nessun segnale dell'utente arrivato per farlo ruotare)."}];
var BRIEF_TEXT="Il lavoro del giorno è una revisione sistematica su The Knee: nella ricostruzione isolata del legamento femororotuleo mediale, il MPFL, la fissazione onlay sul femore appare comparabile al tunnel osseo. Su ottanta studi e quattromilacento adulti, il Kujala medio è 91,4 con l'onlay, intervallo di confidenza da 88,6 a 94,1, contro 87,9 con il tunnel, da 86,7 a 89,0; la ridislocazione è 1,7% contro 2,0%, con intervalli che si sovrappongono. Il limite: l'onlay riguarda duecentoquarantanove pazienti, il confronto è indiretto e l'abstract non riporta il disegno degli studi. Comparabile, non superiore.\n\nSul crociato e sulle multilegamentose, due note di tecnica e una serie. La prima descrive la ricostruzione combinata del crociato anteriore e dell'angolo postero-laterale con un solo tunnel femorale e con il tuo retto femorale più il semitendinoso: nessun paziente, nessun esito. La seconda propone di aumentare un hamstring corto con uno scaffold bioinduttivo per fare crociato e legamento anterolaterale insieme: anch'essa senza dati. La serie prospettica di trenta ricostruzioni del collaterale mediale con rerouting del semitendinoso riporta a dodici mesi stabilità e funzione migliorate, anche nelle lesioni multilegamentose, ma con più complicanze in queste e senza confronti.\n\nAltre schede. Osteotomia tibiale d'apertura mediale: a ventiquattro mesi il dolore scende più nel gruppo con artrosi KL3, quindici pazienti, con un follow-up ancora breve. Un nuovo punteggio da risonanza per l'osso dopo ricostruzione osteocondrale, con Filardo fra gli autori, misura la ripetibilità fra lettori, non l'esito. Un indice per il menisco laterale ipermobile ha AUC 0,84 con sola validazione interna. Nel confronto fra bottone e vite con graffa nel crociato con hamstring non emerge un vantaggio netto. Chiude una proiezione da registri di diciassette paesi: le revisioni di protesi di ginocchio potrebbero crescere del quarantuno per cento entro il 2060.\n\nRichiami, ritrattazioni e linee guida: nessuna novità nel perimetro. Nessuna tensione si sposta oggi.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Il lavoro di oggi è una revisione sistematica su The Knee: nel MPFL, la fissazione femorale onlay confrontata con il tunnel osseo."}, {"chi": "B", "t": "Quanti studi e che cosa trova?"}, {"chi": "A", "t": "Ottanta studi, quattromilacento adulti operati di sola ricostruzione del MPFL. Kujala medio 91,4 con l'onlay, intervallo da 88,6 a 94,1, contro 87,9 con il tunnel, da 86,7 a 89,0. Ridislocazione 1,7% contro 2,0%."}, {"chi": "B", "t": "Quindi l'onlay è meglio?"}, {"chi": "A", "t": "No: gli intervalli si sovrappongono, e l'onlay riguarda solo duecentoquarantanove pazienti. È un confronto indiretto, fra gruppi di studi diversi. Gli autori dicono comparabile, alternativa sicura quando il tunnel non è possibile."}, {"chi": "B", "t": "E per il tuo crociato con il retto femorale?"}, {"chi": "A", "t": "C'è una nota di tecnica proprio sul retto femorale: crociato e angolo postero-laterale con un solo tunnel femorale, insieme al semitendinoso. Ma è una descrizione, senza pazienti né esiti."}, {"chi": "B", "t": "Altre note di tecnica?"}, {"chi": "A", "t": "Una seconda: crociato e legamento anterolaterale con un hamstring aumentato da uno scaffold bioinduttivo, per i pazienti piccoli. Anche qui nessun dato clinico."}, {"chi": "B", "t": "E sul collaterale mediale?"}, {"chi": "A", "t": "Una serie prospettica di trenta ricostruzioni con rerouting del semitendinoso: a dodici mesi stabilità e funzione migliorate, anche nelle multilegamentose, ma con più complicanze e senza confronto con altre tecniche."}, {"chi": "B", "t": "L'osteotomia?"}, {"chi": "A", "t": "A ventiquattro mesi il dolore scende di più nei quindici pazienti con artrosi KL3 che negli altri: follow-up breve, gruppo piccolo."}, {"chi": "B", "t": "Richiami, ritrattazioni, linee guida?"}, {"chi": "A", "t": "Nessuna novità nel perimetro e nessuna tensione si sposta oggi."}];
